test("claim id is excluded so an exact match on the four fields is one duplicate group", function () {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.equal(result.groups[0].claimIds.length, 2);
  assert.ok(result.groups[0].claimIds.indexOf("C-1") !== -1);
  assert.ok(result.groups[0].claimIds.indexOf("C-2") !== -1);
  assert.equal(result.groups[0].patientRef, "P-001");
  assert.equal(result.groups[0].serviceDate, "2024-03-05");
  assert.equal(result.groups[0].procedureCode, "99213");
  assert.equal(result.groups[0].amount, 120.00);
});

test("all four compared fields must match exactly so a different amount is not flagged", function () {
  var claims = [
    { claimId: "C-3", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-4", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 125.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(result.groups, []);
});

test("matching claims form one group and every claim in it is flagged", function () {
  var claims = [
    { claimId: "C-5", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80.00 },
    { claimId: "C-6", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80.00 },
    { claimId: "C-7", patientRef: "P-003", serviceDate: "2024-03-06", procedureCode: "99214", amount: 80.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.equal(result.groups[0].claimIds.length, 3);
  assert.ok(result.groups[0].claimIds.indexOf("C-5") !== -1);
  assert.ok(result.groups[0].claimIds.indexOf("C-6") !== -1);
  assert.ok(result.groups[0].claimIds.indexOf("C-7") !== -1);
  assert.equal(result.groups[0].patientRef, "P-003");
  assert.equal(result.groups[0].serviceDate, "2024-03-06");
  assert.equal(result.groups[0].procedureCode, "99214");
  assert.equal(result.groups[0].amount, 80.00);
});

test("claims in different batches are not compared", function () {
  var batchA = [
    { claimId: "C-8", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120.00 }
  ];
  var batchB = [
    { claimId: "C-9", patientRef: "P-004", serviceDate: "2024-03-07", procedureCode: "99213", amount: 120.00 }
  ];
  assert.deepEqual(code.findDuplicateGroups(batchA).groups, []);
  assert.deepEqual(code.findDuplicateGroups(batchB).groups, []);
});

test("the review list shows each duplicate group with its claim ids and the four matched values", function () {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.equal(result.groups.length, 1);
  assert.equal(result.groups[0].claimIds.length, 2);
  assert.ok(result.groups[0].claimIds.indexOf("C-1") !== -1);
  assert.ok(result.groups[0].claimIds.indexOf("C-2") !== -1);
  assert.equal(result.groups[0].patientRef, "P-001");
  assert.equal(result.groups[0].serviceDate, "2024-03-05");
  assert.equal(result.groups[0].procedureCode, "99213");
  assert.equal(result.groups[0].amount, 120.00);
});

test("claims that belong to no group are not flagged and do not appear", function () {
  var claims = [
    { claimId: "C-3", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-4", patientRef: "P-002", serviceDate: "2024-03-05", procedureCode: "99213", amount: 125.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(result.groups, []);
});

test("no claim is deleted edited or rejected when a duplicate group is flagged", function () {
  var claims = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var snapshot = [
    { claimId: "C-1", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-2", patientRef: "P-001", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 }
  ];
  var result = code.findDuplicateGroups(claims);
  assert.deepEqual(claims, snapshot);
  assert.equal(claims.length, 2);
  assert.equal(result.groups.length, 1);
  assert.ok(result.groups[0].claimIds.indexOf("C-1") !== -1);
  assert.ok(result.groups[0].claimIds.indexOf("C-2") !== -1);
});

test("near matches on amount or service date are not flagged", function () {
  var centsApart = [
    { claimId: "C-10", patientRef: "P-005", serviceDate: "2024-03-08", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-11", patientRef: "P-005", serviceDate: "2024-03-08", procedureCode: "99213", amount: 120.03 }
  ];
  var dayApart = [
    { claimId: "C-12", patientRef: "P-006", serviceDate: "2024-03-05", procedureCode: "99213", amount: 120.00 },
    { claimId: "C-13", patientRef: "P-006", serviceDate: "2024-03-06", procedureCode: "99213", amount: 120.00 }
  ];
  assert.deepEqual(code.findDuplicateGroups(centsApart).groups, []);
  assert.deepEqual(code.findDuplicateGroups(dayApart).groups, []);
});
